import java.awt.Component;
import java.awt.Container;
import javax.swing.JTable;
import javax.swing.table.TableModel;

public class TableModelPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Component find(Container root, String name) {
        for (Component c : root.getComponents()) {
            if (name.equals(c.getName())) {
                return c;
            }
            if (c instanceof Container) {
                Component found = find((Container) c, name);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    static TableModel modelOf(TableModelPanel panel) {
        Component c = find(panel, "table");
        return c instanceof JTable ? ((JTable) c).getModel() : null;
    }

    public static void main(String[] args) {
        try {
            TableModelPanel panel = new TableModelPanel();
            TableModel model = modelOf(panel);

            check("a JTable named table exists", true, model != null);
            check("column headers", "Name/Score", model == null ? null
                    : model.getColumnName(0) + "/" + model.getColumnName(1));
            check("empty table rowCount", 0, panel.rowCount());

            panel.addRow("Ada", 91);
            panel.addRow("Bo", 74);
            panel.addRow("Cy", 88);

            check("rowCount after three addRow calls", 3, panel.rowCount());
            check("the model really holds the rows", 3, model == null ? null : model.getRowCount());
            check("second row read through the model", "Bo/74", model == null ? null
                    : model.getValueAt(1, 0) + "/" + model.getValueAt(1, 1));
            check("topScore", 91, panel.topScore());

            panel.addRow("Di", 95);
            check("topScore after a new leader", 95, panel.topScore());
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

