import javax.swing.JPanel;
import javax.swing.JTable;
import javax.swing.table.DefaultTableModel;

public class TableModelPanel extends JPanel {

    private final DefaultTableModel model = new DefaultTableModel(new String[] {"Name", "Score"}, 0);
    private final JTable table = new JTable(model);

    public TableModelPanel() {
        table.setName("table");
        add(table);
    }

    public void addRow(String name, int score) {
        model.addRow(new Object[] { name, score });
    }

    public int rowCount() {
        return model.getRowCount();
    }

    public int topScore() {
        int best = 0;
        for (int row = 0; row < model.getRowCount(); row++) {
            int score = (Integer) model.getValueAt(row, 1);
            if (score > best) {
                best = score;
            }
        }
        return best;
    }
}
